describe("approving a knowledge proposal", () => {
  it("writes a CANDIDATE, never trusted - the load-bearing invariant", async () => {
    const id = await addProposal("knowledge", { title: "a fact", body: "the body", kind: "pitfall" })
    const res = await decideProposalAction(projectId, id, "approved")
    expect(res.result).toBe(true)

    const rows = await db.select({ state: knowledge.validationState, source: knowledge.sourceKind }).from(knowledge).where(eq(knowledge.projectId, projectId))
    expect(rows).toHaveLength(1)
    expect(rows[0]!.state).toBe("candidate")   // NOT trusted
    expect(rows[0]!.source).toBe("proposer")

    const [prop] = await db.select({ s: knowledgeProposals.status }).from(knowledgeProposals).where(eq(knowledgeProposals.id, id))
    expect(prop!.s).toBe("approved")
  })

  it("is refused for a write grant, and writes no knowledge", async () => {
    const id = await addProposal("knowledge", { title: "x", body: "y", kind: "fact" })
    actingUserId = WRITER
    const res = await decideProposalAction(projectId, id, "approved")
    expect(res.result).toBe(false)
    expect(await db.select().from(knowledge).where(eq(knowledge.projectId, projectId))).toHaveLength(0)
    const [prop] = await db.select({ s: knowledgeProposals.status }).from(knowledgeProposals).where(eq(knowledgeProposals.id, id))
    expect(prop!.s).toBe("pending") // untouched
  })
})

describe("rejecting a proposal", () => {
  it("closes it without writing knowledge", async () => {
    const id = await addProposal("knowledge", { title: "x", body: "y", kind: "fact" })
    const res = await decideProposalAction(projectId, id, "rejected")
    expect(res.result).toBe(true)
    expect(await db.select().from(knowledge).where(eq(knowledge.projectId, projectId))).toHaveLength(0)
    const [prop] = await db.select({ s: knowledgeProposals.status }).from(knowledgeProposals).where(eq(knowledgeProposals.id, id))
    expect(prop!.s).toBe("rejected")
  })

  it("a second decision on an already-decided proposal is refused, nothing re-written", async () => {
    const id = await addProposal("knowledge", { title: "x", body: "y", kind: "fact" })
    expect((await decideProposalAction(projectId, id, "approved")).result).toBe(true)
    const before = await db.select().from(knowledge).where(eq(knowledge.projectId, projectId))
    // Re-decide: not_pending -> refused.
    expect((await decideProposalAction(projectId, id, "rejected")).result).toBe(false)
    expect(await db.select().from(knowledge).where(eq(knowledge.projectId, projectId))).toHaveLength(before.length)
  })
})

describe("approving a playbook proposal", () => {
  it("applies content, versions it, and is rollback-able", async () => {
    const id = await addProposal("playbook", { content: "NEW BODY" })
    const res = await decideProposalAction(projectId, id, "approved")
    expect(res.result).toBe(true)

    const [proj] = await db.select({ md: projects.relayroomMd }).from(projects).where(eq(projects.id, projectId))
    expect(proj!.md).toBe("NEW BODY")
    const versions = await db.select({ v: playbookVersions.version, c: playbookVersions.content }).from(playbookVersions).where(eq(playbookVersions.projectId, projectId))
    expect(versions.length).toBeGreaterThanOrEqual(1)
    expect(versions.some((v) => v.c === "NEW BODY")).toBe(true)
  })
})

describe("rollbackPlaybookAction", () => {
  it("owner rolls back to a prior version by appending a new one", async () => {
    // Two playbook approvals -> versions 1 (V1) and 2 (V2), current = V2.
    await decideProposalAction(projectId, await addProposal("playbook", { content: "V1" }), "approved")
    await decideProposalAction(projectId, await addProposal("playbook", { content: "V2" }), "approved")

    const res = await rollbackPlaybookAction(projectId, 1)
    expect(res.result).toBe(true)

    const [proj] = await db.select({ md: projects.relayroomMd }).from(projects).where(eq(projects.id, projectId))
    expect(proj!.md).toBe("V1") // served content is now V1's

    // Append-only: a new highest version exists, and V2's row still there.
    const versions = await db.select({ v: playbookVersions.version, c: playbookVersions.content }).from(playbookVersions).where(eq(playbookVersions.projectId, projectId))
    expect(versions.some((r) => r.c === "V2")).toBe(true)      // history kept
    expect(Math.max(...versions.map((r) => r.v))).toBeGreaterThanOrEqual(3) // new version appended
  })

  it("is refused for a write grant", async () => {
    await decideProposalAction(projectId, await addProposal("playbook", { content: "V1" }), "approved")
    actingUserId = WRITER
    const res = await rollbackPlaybookAction(projectId, 1)
    expect(res.result).toBe(false)
  })

  it("refuses a version that does not exist", async () => {
    const res = await rollbackPlaybookAction(projectId, 99)
    expect(res.result).toBe(false)
  })
})

/**
 * Bearer enforcement on the connect-code endpoints (SRV-H2).
 *
 * The connect code is project-wide, travels in the URL path, never expires, and a
 * ban cannot take it away - banProjectMember deletes the member's tokens, which
 * shut the MCP path immediately while these endpoints kept answering. `part` was
 * an unauthenticated claim on top of that, so a code-holder could name any part
 * and read its unread subjects.
 *
 * Now the token is authoritative for (user, project) and `part` is checked against
 * it. The token cannot IDENTIFY a part - one token can hold agent_connection rows
 * for several parts - so the request still names one and the caller must own it.
 *
 * Two enforcement levels, by whether an un-upgraded client would fail LOUDLY:
 *   required - /wake/claim, /wake/delivered, /pending-wake. The pager and the
 *              channel already send the header, and a pager that cannot claim a
 *              lease stops nudging where someone will notice.
 *   grace    - /heartbeat, /usage, /role, /relayroom-md, /unread. Each of these
 *              fails silently in a client that has not been upgraded: the
 *              ask-guard fails open, the usage hook swallows its errors, and the
 *              tmux status bar's inbox counter keeps displaying its last value.
 */
import { randomBytes } from 'node:crypto'
import { afterAll, beforeAll, describe, expect, it } from 'vitest'
import { eq } from 'drizzle-orm'
import { agents, projectAccess, projects } from '@relayroom/db'
import postgres from 'postgres'
import { makeTestApp, TEST_DATABASE_URL } from './helpers'

const { app, db, bus } = makeTestApp()
const rawSql = postgres(TEST_DATABASE_URL)

afterAll(async () => {
  await bus.close()
  await db.$client.end()
  await rawSql.end()
})

const CLIENT_ID = 'relayroom-runtime-auth-client'

beforeAll(async () => {
  await rawSql`
    INSERT INTO better_auth_oauth_application
      (id, name, client_id, client_secret, redirect_urls, type, disabled, created_at, updated_at)
    VALUES ('runtime-auth-client', 'Runtime Auth Test Client', ${CLIENT_ID},
            NULL, 'urn:ietf:wg:oauth:2.0:oob', 'internal', false, NOW(), NOW())
    ON CONFLICT (client_id) DO NOTHING`
})

async function makeUser(orgId: string, sfx: string): Promise<{ userId: string; token: string }> {
  const userId = `ra-user-${sfx}`
  await rawSql`
    INSERT INTO better_auth_user (id, name, email, email_verified, created_at, updated_at)
    VALUES (${userId}, ${'User ' + userId}, ${userId + '@runtime.test'}, true, NOW(), NOW())`
  await rawSql`
    INSERT INTO better_auth_member (id, organization_id, user_id, role, created_at)
    VALUES (${'ra-mem-' + sfx}, ${orgId}, ${userId}, 'member', NOW())`
  const token = randomBytes(24).toString('hex')
  await rawSql`
    INSERT INTO better_auth_oauth_access_token
      (id, access_token, access_token_expires_at, client_id, user_id, scopes, created_at, updated_at)
    VALUES (${'ra-tok-' + sfx}, ${token}, ${new Date(Date.now() + 3600_000)},
            ${CLIENT_ID}, ${userId}, 'openid profile', NOW(), NOW())`
  return { userId, token }
}

interface Scene {
  projectId: string
  connectCode: string
  orgId: string
  owner: { userId: string; token: string }
  agentId: string
}

/** A project with one part owned by `owner`. */
async function scene(part = 'worker'): Promise<Scene> {
  const sfx = randomBytes(6).toString('hex')
  const orgId = `ra-org-${sfx}`
  await rawSql`
    INSERT INTO better_auth_organization (id, name, created_at)
    VALUES (${orgId}, ${'Org ' + orgId}, NOW())`

  const owner = await makeUser(orgId, sfx)
  const connectCode = `ra-cc-${sfx}`
  const [project] = await db.insert(projects).values({
    organizationId: orgId, slug: `ra-proj-${sfx}`, name: 'Runtime Auth Project', connectCode,
  }).returning({ id: projects.id })

  const [agent] = await db.insert(agents)
    .values({ projectId: project!.id, part, ownerUserId: owner.userId })
    .returning({ id: agents.id })

  return { projectId: project!.id, connectCode, orgId, owner, agentId: agent!.id }
}

const bearer = (t: string) => ({ Authorization: `Bearer ${t}` })

describe('bearer required (wake delivery)', () => {
  it('/wake/claim refuses a request with no bearer token, with a challenge header', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/wake/claim`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ part: 'worker', holder: 'h1' }),
    })
    expect(res.status).toBe(401)
    expect(res.headers.get('WWW-Authenticate')).toMatch(/Bearer/)
  })

  it('/wake/claim and /pending-wake refuse a request with no bearer token', async () => {
    const s = await scene()
    const claim = await app.request(`/mcp/${s.connectCode}/wake/claim`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ part: 'worker', holder: 'h1' }),
    })
    expect(claim.status).toBe(401)

    const pending = await app.request(`/mcp/${s.connectCode}/pending-wake?part=worker&holder=h1`)
    expect(pending.status).toBe(401)
  })

  it('/wake/claim still works for the owning pager', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/wake/claim`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...bearer(s.owner.token) },
      body: JSON.stringify({ part: 'worker', holder: 'h1' }),
    })
    // No active wake to lease, but it got past authorization - that is the point.
    expect(res.status).toBe(200)
    expect((await res.json()) as { noWake?: boolean }).toMatchObject({ noWake: true })
  })
})

describe('grace period (clients that fail silently)', () => {
  it('/unread still answers the tmux status bar, which sends no token', async () => {
    // The inbox counter in the status bar is a curl line in the generated rr.sh
    // (packages/cli/src/init.ts). It has no Authorization header yet, and on a
    // failed fetch it keeps displaying its last value - so rejecting it here would
    // freeze the number rather than show anyone an error.
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=worker`)
    expect(res.status).toBe(200)
  })


  it('/heartbeat still accepts a client that sends no bearer token', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/heartbeat`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ part: 'worker' }),
    })
    expect(res.status).toBe(200)
  })

  it('/heartbeat accepts the owner when the token IS sent', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/heartbeat`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...bearer(s.owner.token) },
      body: JSON.stringify({ part: 'worker' }),
    })
    expect(res.status).toBe(200)
  })

  it('a BAD token is rejected rather than falling back to the legacy path', async () => {
    // The grace period is for clients that send nothing yet. A token that is present
    // but expired or revoked must fail: silently downgrading it to weaker auth would
    // undo the expiry it is being checked for.
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/heartbeat`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...bearer('not-a-real-token') },
      body: JSON.stringify({ part: 'worker' }),
    })
    expect(res.status).toBe(401)
  })

  it('a banned member is refused even on a grace endpoint when the token is sent', async () => {
    const s = await scene()
    await db.insert(projectAccess).values({
      projectId: s.projectId, userId: s.owner.userId, level: 'write', bannedAt: new Date(),
    })
    const res = await app.request(`/mcp/${s.connectCode}/heartbeat`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...bearer(s.owner.token) },
      body: JSON.stringify({ part: 'worker' }),
    })
    expect(res.status).toBe(403)
  })

  it('/relayroom-md authorizes at project level, with no part', async () => {
    const s = await scene()
    const withToken = await app.request(`/mcp/${s.connectCode}/relayroom-md`, {
      headers: bearer(s.owner.token),
    })
    expect(withToken.status).toBe(200)

    // A member of a DIFFERENT org has no business reading this project's playbook.
    const otherOrg = `ra-org-out-${randomBytes(6).toString('hex')}`
    await rawSql`
      INSERT INTO better_auth_organization (id, name, created_at)
      VALUES (${otherOrg}, 'Outsider Org', NOW())`
    const outsider = await makeUser(otherOrg, randomBytes(6).toString('hex'))
    const res = await app.request(`/mcp/${s.connectCode}/relayroom-md`, {
      headers: bearer(outsider.token),
    })
    expect(res.status).toBe(403)
  })
})

describe('part ownership', () => {
  it('/unread accepts the part owner', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=worker`, {
      headers: bearer(s.owner.token),
    })
    expect(res.status).toBe(200)
  })

  it('/unread refuses another member reading a part they do not own', async () => {
    const s = await scene()
    // A second member of the same org: authenticated, in the project, not the owner.
    const other = await makeUser(s.orgId, randomBytes(6).toString('hex'))
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=worker`, {
      headers: bearer(other.token),
    })
    expect(res.status).toBe(403)
  })

  it('/unread refuses a banned member who still holds the connect code', async () => {
    const s = await scene()
    // The ban is what the connect code could not express: the code is project-wide,
    // so it cannot be rotated for one member without cutting off everyone.
    await db.insert(projectAccess).values({
      projectId: s.projectId, userId: s.owner.userId, level: 'write', bannedAt: new Date(),
    })
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=worker`, {
      headers: bearer(s.owner.token),
    })
    expect(res.status).toBe(403)
    expect(((await res.json()) as { error: string }).error).toMatch(/banned/)
  })

  it('a deleted part is refused even for its owner', async () => {
    const s = await scene()
    await db.update(agents).set({ deletedAt: new Date() }).where(eq(agents.id, s.agentId))
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=worker`, {
      headers: bearer(s.owner.token),
    })
    expect(res.status).toBe(404)
  })

  it('an unregistered part is refused', async () => {
    const s = await scene()
    const res = await app.request(`/mcp/${s.connectCode}/unread?part=ghostpart`, {
      headers: bearer(s.owner.token),
    })
    expect(res.status).toBe(404)
  })
})

/**
 * The redaction denylist write.
 *
 * Two things are worth pinning here and nothing else is. First, the gate: the save
 * button only renders for owners, but the action is reachable without the button,
 * so ownership has to be decided here. Second, that a configuration the resolver
 * refuses is not stored - if it were, distillation would stop for the project and
 * the owner would have been told their save succeeded.
 *
 * What is deliberately NOT tested here is which rules are valid. That judgement
 * lives in `resolveRedactionRules` in `@relayroom/shared` and is tested there. A
 * copy of it in this file would be a second answer to the same question, free to
 * drift from the one the server actually enforces - which is the whole reason this
 * action calls the shared resolver instead of checking rules itself.
 */
import { afterAll, beforeEach, describe, expect, it, vi } from "vitest"
import { eq, sql } from "drizzle-orm"

let actingUserId = "rd-owner"

vi.mock("@/lib/auth-session", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@/lib/auth-session")>()
  return { ...actual, getServerSession: vi.fn(async () => ({ user: { id: actingUserId } })) }
})

import { resolveRedactionRules } from "@relayroom/shared"
import { db } from "@/lib/db"
import { projects, projectAccess } from "@relayroom/db/schema"
import { better_auth_user, better_auth_organization, better_auth_member } from "@relayroom/db/auth-schema"
import { saveRedactionRules } from "./redaction-actions"

const ORG = "org-rd"
const OWNER = "rd-owner"
const WRITER = "rd-writer"

let projectId: string

async function seedMember(id: string) {
  await db.insert(better_auth_user).values({ id, name: id, email: `${id}@t.local`, emailVerified: true }).onConflictDoNothing()
  await db.insert(better_auth_member).values({ id: `m-${id}`, organizationId: ORG, userId: id, role: "member", createdAt: new Date() }).onConflictDoNothing()
}

async function storedConfig(): Promise<Record<string, unknown>> {
  const [p] = await db.select({ c: projects.knowledgeConfig }).from(projects).where(eq(projects.id, projectId))
  return (p?.c ?? {}) as Record<string, unknown>
}

async function storedRules(): Promise<unknown> {
  return (await storedConfig()).redactionRules
}

beforeEach(async () => {
  actingUserId = OWNER
  await db.delete(projectAccess)
  await db.delete(projects).where(eq(projects.organizationId, ORG))
  await db.delete(better_auth_member).where(eq(better_auth_member.organizationId, ORG))
  await db.insert(better_auth_organization).values({ id: ORG, name: ORG, createdAt: new Date() }).onConflictDoNothing()
  await seedMember(OWNER)
  await seedMember(WRITER)

  const [p] = await db
    .insert(projects)
    .values({ organizationId: ORG, slug: "rd", name: "RD", connectCode: "rd-cc", createdByUserId: OWNER })
    .returning({ id: projects.id })
  projectId = p!.id
  await db.insert(projectAccess).values([
    { projectId, userId: OWNER, level: "owner", createdByUserId: OWNER },
    { projectId, userId: WRITER, level: "write", createdByUserId: OWNER },
  ])
})

afterAll(async () => {
  await db.$client.end()
})

describe("saveRedactionRules", () => {
  it("stores what an owner saves", async () => {
    const res = await saveRedactionRules(projectId, [{ kind: "literal", value: "acme-internal" }])

    expect(res.result).toBe(true)
    expect(await storedRules()).toEqual([{ kind: "literal", value: "acme-internal" }])
  })

  it("refuses a write member, who can reach the action without the button", async () => {
    actingUserId = WRITER

    const res = await saveRedactionRules(projectId, [{ kind: "literal", value: "acme-internal" }])

    expect(res.result).toBe(false)
    expect(await storedRules()).toBeUndefined()
  })

  it("stores nothing when the resolver refuses the configuration", async () => {
    // A rule the resolver cannot resolve makes every knowledge write fail closed.
    // Storing it and warning afterwards would stop the project's distillation while
    // the owner believed they had just configured protection - so the save has to
    // fail instead. Which rules are refused is the resolver's call, not this test's;
    // this one only needs an input it rejects.
    await saveRedactionRules(projectId, [{ kind: "literal", value: "acme-internal" }])

    const res = await saveRedactionRules(projectId, [{ kind: "not-a-rule" }])

    expect(res.result).toBe(false)
    // The previous configuration is still the one in force. A refused save must not
    // leave the project with neither the old rules nor the new ones.
    expect(await storedRules()).toEqual([{ kind: "literal", value: "acme-internal" }])
  })

  it("frees a project whose config still holds the legacy key", async () => {
    // The recovery path, and the reason it is a release blocker rather than tidiness.
    // The resolver refuses any project whose config carries `redactionPatterns`, and
    // refusing means every knowledge write for that project fails closed. This save is
    // the only remedy the product offers, and the card tells the owner it replaces
    // those settings - so the assertion is that the resolver actually passes
    // afterwards, not that the key is gone. Gone-from-the-column is the mechanism; the
    // thing that was broken is that writers stayed blocked.
    // Seeded through raw SQL because the typed setter will not accept it: the key was
    // deleted from the column's TypeScript shape when the rule union replaced it. That
    // is the situation being tested rather than an obstacle to it - the rows that carry
    // this key predate the type, and a type is a claim about what should be in a JSONB
    // column, never a check of what is.
    await db
      .update(projects)
      .set({
        knowledgeConfig: sql`'{"redactionPatterns":["ACME"],"distillOnClose":true}'::jsonb`,
      })
      .where(eq(projects.id, projectId))

    // Precondition, stated as a check rather than assumed. Without it a resolver that
    // stopped refusing the legacy key for any other reason would leave this test green
    // while proving nothing.
    expect(resolveRedactionRules(await storedConfig()).unresolved).not.toEqual([])

    const res = await saveRedactionRules(projectId, [{ kind: "literal", value: "acme-internal" }])

    expect(res.result).toBe(true)
    expect(resolveRedactionRules(await storedConfig()).unresolved).toEqual([])

    // The removal is scoped to the legacy key. `distillOnClose` gains a write path in
    // this release, so a save that cleared the column wholesale would silently undo a
    // setting the owner made on another screen.
    expect((await storedConfig()).distillOnClose).toBe(true)
  })

  it("accepts an empty denylist, which is how redaction gets turned off", async () => {
    // Removing every rule is a legitimate save and the recovery path for an
    // over-broad rule, so it must not be mistaken for an empty/no-op submission.
    await saveRedactionRules(projectId, [{ kind: "literal", value: "acme-internal" }])

    const res = await saveRedactionRules(projectId, [])

    expect(res.result).toBe(true)
    expect(await storedRules()).toEqual([])
  })
})

