describe("regenerateConnectCode (AC-1: owner required)", () => {
  it("a write member is denied (not owner)", async () => {
    actingUserId = WRITER
    const [before] = await db.select({ connectCode: projects.connectCode }).from(projects).where(eq(projects.id, projectId))
    const res = await regenerateConnectCode(projectId)
    expect(res.result).toBe(false)
    const [after] = await db.select({ connectCode: projects.connectCode }).from(projects).where(eq(projects.id, projectId))
    expect(after?.connectCode).toBe(before?.connectCode)
  })

  it("an owner can regenerate", async () => {
    actingUserId = OWNER
    const [before] = await db.select({ connectCode: projects.connectCode }).from(projects).where(eq(projects.id, projectId))
    const res = await regenerateConnectCode(projectId)
    expect(res.result).toBe(true)
    if (res.result) expect(res.item.connectCode).not.toBe(before?.connectCode)
  })
})

"use server"

import { randomBytes } from "node:crypto"
import { and, eq } from "drizzle-orm"
import type { ApiResult, ApiResultWithItem } from "@relayroom/shared"
import { db } from "@/modules/drizzle/db"
import { projects, knowledgeCheckMap, knowledgeAudits, knowledge } from "@relayroom/db/schema"
import { getServerSession, requireProjectAccess } from "@/lib/auth-session"
import { getErrorTranslations } from "@/lib/action-i18n"
import {
  addCheckMappingSchema,
  isRotationMode,
  type AddCheckMappingInput,
  type RotationMode,
} from "./attest-schema"
import { isUuid } from "@/lib/uuid"

/**
 * How long the rotated-away secret keeps verifying after a rotation.
 *
 * A grace window exists so a routine rotation does not break the CI configs that
 * still carry the old secret the instant the owner clicks. 24h is enough for an
 * owner to roll the secret across their pipelines and short enough to bound how
 * long a replaced secret stays usable.
 *
 * CHOSEN, NOT SPECIFIED: the design says `now() + grace` without a number. 24h is
 * a judgement, not a value from the spec - do not read it as one. Move it to
 * projects.knowledgeConfig if it ever needs to be per-project.
 *
 * The tradeoff cuts the other way when the secret leaked, where any grace is
 * exposure - that is what the `revoke` mode is for. This constant is the grace
 * for the `hygiene` mode only.
 */
const ROTATION_GRACE_MS = 24 * 60 * 60 * 1000

/** The plaintext secret, returned exactly once - the mint response and nowhere else. */
export interface MintedAttestSecret {
  /** Show this to the user once, then it is unrecoverable. */
  secret: string
  /** The public selector for this secret. Safe to display afterwards. */
  keyId: string
}

function newSecret(): string {
  // 32 bytes of entropy, hex. This is an HMAC key, never shown after the mint.
  return randomBytes(32).toString("hex")
}

function newKeyId(): string {
  // A short, public identifier the attest body names to select this key.
  return `k_${randomBytes(4).toString("hex")}`
}

/**
 * Mint the project's first attest secret, or rotate to a new one.
 *
 * The plaintext secret is in the RETURN VALUE and written nowhere a read can
 * reach - see attest-queries. There is intentionally no "show me the secret
 * again" path; the owner copies it now or mints a new one.
 *
 * Rotation is the documented two-slot move (04): the current secret becomes the
 * previous, honored for a grace window, and a fresh current is minted. On the
 * first mint there is no current, so no previous is set. Either way it is
 * `owner`-only and writes an `attest_secret_rotate` audit row - it is an entry
 * in the same ledger promotion writes to, and it cannot be undone.
 *
 * `mode` decides what happens to the secret being replaced:
 *
 * - `hygiene` (default) keeps it alive for ROTATION_GRACE_MS so running pipelines
 *   survive the swap.
 * - `revoke` clears the previous slot in the SAME write, so the replaced secret
 *   stops verifying immediately. The server's key selection requires a non-null,
 *   unexpired previous slot, so nulling the column is the whole revocation - there
 *   is no second place the old secret could still be honored from.
 *
 * What revoke does NOT do: it stops future misuse only. Promotions the leaked
 * secret already caused stay exactly as they are - undoing those is forensics,
 * through the existing refute/demote path. The UI says so; do not let this action
 * be presented as cleanup of the past.
 */
export async function rotateAttestSecret(
  projectId: string,
  mode: RotationMode = "hygiene",
): Promise<ApiResultWithItem<MintedAttestSecret>> {
  const t = await getErrorTranslations()
  try {
    if (!isUuid(projectId)) return { result: false, message: t("project.notFound") }
    // A Server Action's arguments are caller-supplied. An unrecognized mode is
    // refused rather than defaulted: silently reading an unknown value as
    // `hygiene` would leave a secret the owner believes they revoked alive for a
    // day, while the UI reported success.
    if (!isRotationMode(mode)) return { result: false, message: t("common.invalidInput") }

    const session = await getServerSession()
    if (!session) return { result: false, message: t("auth.loginRequired") }

    // `owner`, not `write`: the secret is the root of CI's authority to promote.
    // The action re-checks even though the page hides the control - a Server
    // Action is a live endpoint reachable without the page.
    const access = await requireProjectAccess(session.user.id, projectId, "owner")
    if (!access.ok) return { result: false, message: access.message }

    const secret = newSecret()
    const keyId = newKeyId()

    const minted = await db.transaction(async (tx) => {
      // Read the current slot under the row so a concurrent rotation cannot
      // interleave and lose one side of the copy.
      const [current] = await tx
        .select({
          secret: projects.attestSecret,
          keyId: projects.attestKeyId,
        })
        .from(projects)
        .where(eq(projects.id, projectId))
        .for("update")
      if (!current) return null

      const rotating = current.secret != null
      // `revoke` keeps no previous at all - not a shorter grace, none. Anything
      // else would leave a window on a secret assumed compromised.
      const keepsPrev = rotating && mode === "hygiene"
      const graceUntil = keepsPrev ? new Date(Date.now() + ROTATION_GRACE_MS) : null

      await tx
        .update(projects)
        .set({
          attestSecret: secret,
          attestKeyId: keyId,
          // Current -> previous, honored for the grace window. On a first mint
          // (no current) and on a revoke, the previous slot is left empty.
          attestSecretPrev: keepsPrev ? current.secret : null,
          attestKeyIdPrev: keepsPrev ? current.keyId : null,
          attestSecretPrevExpiresAt: graceUntil,
          updatedAt: new Date(),
        })
        .where(eq(projects.id, projectId))

      await tx.insert(knowledgeAudits).values({
        projectId,
        action: "attest_secret_rotate",
        actorKind: "human",
        actorUserId: session.user.id,
        // The plaintext is never recorded; the audit names the key ids and whether
        // this replaced a live secret, which is what an operator needs to trace it.
        // `reason` separates a routine rotation from an incident response, and
        // `graceUntil` records whether the replaced key was left usable - the two
        // things a later forensic read needs and cannot infer from the row itself.
        detail: {
          keyId,
          prevKeyId: rotating ? current.keyId : null,
          firstMint: !rotating,
          reason: mode === "revoke" ? "incident" : "hygiene",
          revokedPrev: rotating && mode === "revoke",
          graceUntil: graceUntil?.toISOString() ?? null,
        },
      })

      return true
    })

    if (!minted) return { result: false, message: t("project.notFound") }
    return { result: true, item: { secret, keyId } }
  } catch (err) {
    console.error("[rotateAttestSecret]", err)
    return { result: false, message: t("attest.rotateFailed") }
  }
}

/**
 * Map a CI check to a claim, so a passing run of that check counts toward the
 * claim's promotion. Without a mapping an attestation is recorded `counted=false`
 * and never promotes, so this screen is where an owner decides what CI may vouch
 * for.
 *
 * The (project, knowledge) pairing is enforced two ways: the claim is confirmed
 * to belong to THIS project before the insert, and the table's composite FK
 * rejects a cross-project pair even if that check were bypassed.
 */
export async function addCheckMapping(input: AddCheckMappingInput): Promise<ApiResult> {
  const t = await getErrorTranslations()
  try {
    const session = await getServerSession()
    if (!session) return { result: false, message: t("auth.loginRequired") }

    const parsed = addCheckMappingSchema(t).safeParse(input)
    if (!parsed.success) {
      return { result: false, message: parsed.error.issues[0]?.message ?? t("common.invalidInput") }
    }
    const { projectId, knowledgeId, checkName } = parsed.data

    const access = await requireProjectAccess(session.user.id, projectId, "owner")
    if (!access.ok) return { result: false, message: access.message }

    // The claim must belong to this project. This is the tenant check in
    // application terms; the composite FK is the backstop, not the primary gate.
    const [entry] = await db
      .select({ id: knowledge.id })
      .from(knowledge)
      .where(and(eq(knowledge.id, knowledgeId), eq(knowledge.projectId, projectId)))
      .limit(1)
    if (!entry) return { result: false, message: t("knowledge.notFound") }

    await db
      .insert(knowledgeCheckMap)
      .values({ projectId, checkName, knowledgeId, createdByUserId: session.user.id })
      // The unique index makes a duplicate mapping a no-op rather than an error.
      .onConflictDoNothing()

    await db.insert(knowledgeAudits).values({
      projectId,
      action: "check_map_change",
      knowledgeId,
      actorKind: "human",
      actorUserId: session.user.id,
      detail: { change: "add", checkName },
    })

    return { result: true }
  } catch (err) {
    console.error("[addCheckMapping]", err)
    return { result: false, message: t("attest.mapFailed") }
  }
}

/** Remove a check -> claim mapping. Owner-only; audited. */
export async function removeCheckMapping(mappingId: string): Promise<ApiResult> {
  const t = await getErrorTranslations()
  try {
    if (!isUuid(mappingId)) return { result: false, message: t("attest.mappingNotFound") }

    const session = await getServerSession()
    if (!session) return { result: false, message: t("auth.loginRequired") }

    // Resolve the mapping's project first so authority is checked against the
    // project that owns it, not one the caller supplies.
    const [mapping] = await db
      .select({ projectId: knowledgeCheckMap.projectId, checkName: knowledgeCheckMap.checkName, knowledgeId: knowledgeCheckMap.knowledgeId })
      .from(knowledgeCheckMap)
      .where(eq(knowledgeCheckMap.id, mappingId))
      .limit(1)
    if (!mapping) return { result: false, message: t("attest.mappingNotFound") }

    const access = await requireProjectAccess(session.user.id, mapping.projectId, "owner")
    if (!access.ok) return { result: false, message: access.message }

    await db.delete(knowledgeCheckMap).where(eq(knowledgeCheckMap.id, mappingId))

    await db.insert(knowledgeAudits).values({
      projectId: mapping.projectId,
      action: "check_map_change",
      knowledgeId: mapping.knowledgeId,
      actorKind: "human",
      actorUserId: session.user.id,
      detail: { change: "remove", checkName: mapping.checkName },
    })

    return { result: true }
  } catch (err) {
    console.error("[removeCheckMapping]", err)
    return { result: false, message: t("attest.mapFailed") }
  }
}

/**
 * Web Server Action tests for governance ban/unban (phase 09).
 *
 * Exercises authorization + guards (requireProjectManage, last-owner, self-ban)
 * and reversibility against the real test DB. The session/active-org lookups are
 * mocked so we can act as different principals.
 */
import { afterAll, beforeEach, describe, expect, it, vi } from "vitest"
import { and, eq } from "drizzle-orm"

// ── Session mocks (control the acting principal per test) ─────────────────────
let actingUserId = "actor-owner"
let activeOrgId: string | null = "org-ban-web"

vi.mock("@/lib/auth-session", () => ({
  getServerSession: vi.fn(async () => ({ user: { id: actingUserId } })),
}))
vi.mock("@/lib/active-org", () => ({
  resolveActiveOrgId: vi.fn(async () => activeOrgId),
}))

import { db } from "@/lib/db"
import { projects, projectAccess } from "@relayroom/db/schema"
import {
  better_auth_user,
  better_auth_organization,
  better_auth_member,
} from "@relayroom/db/auth-schema"
import { banProjectMember, unbanProjectMember } from "./member-actions"

const ORG = "org-ban-web"
const OWNER = "actor-owner" // project owner + org member (manager)
const TARGET = "target-member"
const TARGET2 = "target-member-2"
const READER = "reader-member" // non-manager (write) member

let projectId: string

async function seedUser(id: string) {
  await db
    .insert(better_auth_user)
    .values({ id, name: id, email: `${id}@test.local`, emailVerified: true })
    .onConflictDoNothing()
}

async function seedOrgMember(userId: string, role: string) {
  await db
    .insert(better_auth_member)
    .values({ id: `m-${userId}`, organizationId: ORG, userId, role, createdAt: new Date() })
    .onConflictDoNothing()
}

async function bannedAtOf(pid: string, userId: string): Promise<Date | null> {
  const [row] = await db
    .select({ bannedAt: projectAccess.bannedAt })
    .from(projectAccess)
    .where(and(eq(projectAccess.projectId, pid), eq(projectAccess.userId, userId)))
  return row?.bannedAt ?? null
}

beforeEach(async () => {
  actingUserId = OWNER
  activeOrgId = ORG

  await db.delete(projectAccess)
  await db.delete(projects).where(eq(projects.organizationId, ORG))
  await db.delete(better_auth_member).where(eq(better_auth_member.organizationId, ORG))

  await db
    .insert(better_auth_organization)
    .values({ id: ORG, name: "Ban Web Org", createdAt: new Date() })
    .onConflictDoNothing()
  for (const u of [OWNER, TARGET, TARGET2, READER]) await seedUser(u)
  await seedOrgMember(OWNER, "member")
  await seedOrgMember(TARGET, "member")
  await seedOrgMember(TARGET2, "member")
  await seedOrgMember(READER, "member")

  const [p] = await db
    .insert(projects)
    .values({
      organizationId: ORG,
      slug: `ban-web-${Date.now()}`,
      name: "Ban Web Project",
      connectCode: `ban-web-cc-${Date.now()}`,
      createdByUserId: OWNER,
    })
    .returning({ id: projects.id })
  projectId = p.id

  // OWNER is project owner (manager); TARGET + READER are write members.
  await db.insert(projectAccess).values([
    { projectId, userId: OWNER, level: "owner", createdByUserId: OWNER },
    { projectId, userId: TARGET, level: "write", createdByUserId: OWNER },
    { projectId, userId: READER, level: "write", createdByUserId: OWNER },
  ])
})

afterAll(async () => {
  await db.$client.end()
})

describe("banProjectMember", () => {
  it("project owner (manager) can ban a write member", async () => {
    const res = await banProjectMember({ projectId, userId: TARGET, scope: "project" })
    expect(res.result).toBe(true)
    expect(await bannedAtOf(projectId, TARGET)).not.toBeNull()
  })

  it("org owner/admin can ban a project member", async () => {
    // Acting principal is only an org admin, not a project owner.
    actingUserId = "org-admin"
    await seedUser("org-admin")
    await seedOrgMember("org-admin", "admin")

    const res = await banProjectMember({ projectId, userId: TARGET, scope: "project" })
    expect(res.result).toBe(true)
    expect(await bannedAtOf(projectId, TARGET)).not.toBeNull()
  })

  it("non-manager (write member) cannot ban", async () => {
    actingUserId = READER // write member, not owner/admin
    const res = await banProjectMember({ projectId, userId: TARGET, scope: "project" })
    expect(res.result).toBe(false)
    expect(await bannedAtOf(projectId, TARGET)).toBeNull()
  })

  it("last owner cannot be banned", async () => {
    // OWNER is the sole owner; an org admin tries to ban them.
    actingUserId = "org-admin"
    await seedUser("org-admin")
    await seedOrgMember("org-admin", "admin")

    const res = await banProjectMember({ projectId, userId: OWNER, scope: "project" })
    expect(res.result).toBe(false)
    expect(res.message).toMatch(/owner/)
    expect(await bannedAtOf(projectId, OWNER)).toBeNull()
  })

  it("a manager cannot ban themselves", async () => {
    // Add a second owner so the last-owner guard would otherwise pass.
    await db
      .update(projectAccess)
      .set({ level: "owner" })
      .where(and(eq(projectAccess.projectId, projectId), eq(projectAccess.userId, TARGET)))
    const res = await banProjectMember({ projectId, userId: OWNER, scope: "project" })
    expect(res.result).toBe(false)
    expect(await bannedAtOf(projectId, OWNER)).toBeNull()
  })

  it("is reversible: unban clears bannedAt, row preserved", async () => {
    await banProjectMember({ projectId, userId: TARGET, scope: "project" })
    expect(await bannedAtOf(projectId, TARGET)).not.toBeNull()

    const res = await unbanProjectMember({ projectId, userId: TARGET, scope: "project" })
    expect(res.result).toBe(true)
    expect(await bannedAtOf(projectId, TARGET)).toBeNull()

    // Row still exists (not hard-deleted).
    const [row] = await db
      .select({ userId: projectAccess.userId })
      .from(projectAccess)
      .where(and(eq(projectAccess.projectId, projectId), eq(projectAccess.userId, TARGET)))
    expect(row).toBeTruthy()
  })

  it("org scope bans the member on every project in the org", async () => {
    const [p2] = await db
      .insert(projects)
      .values({
        organizationId: ORG,
        slug: `ban-web-2-${Date.now()}`,
        name: "Second",
        connectCode: `ban-web-cc2-${Date.now()}`,
        createdByUserId: OWNER,
      })
      .returning({ id: projects.id })
    await db.insert(projectAccess).values([
      { projectId: p2.id, userId: OWNER, level: "owner", createdByUserId: OWNER },
      { projectId: p2.id, userId: TARGET, level: "write", createdByUserId: OWNER },
    ])

    const res = await banProjectMember({ projectId, userId: TARGET, scope: "org" })
    expect(res.result).toBe(true)
    expect(await bannedAtOf(projectId, TARGET)).not.toBeNull()
    expect(await bannedAtOf(p2.id, TARGET)).not.toBeNull()
  })

  it("org scope refuses if the target is a last owner on ANY project", async () => {
    // TARGET is the sole owner of a second project: org-scope ban must refuse.
    const [p2] = await db
      .insert(projects)
      .values({
        organizationId: ORG,
        slug: `ban-web-3-${Date.now()}`,
        name: "Third",
        connectCode: `ban-web-cc3-${Date.now()}`,
        createdByUserId: TARGET,
      })
      .returning({ id: projects.id })
    await db
      .insert(projectAccess)
      .values({ projectId: p2.id, userId: TARGET, level: "owner", createdByUserId: TARGET })

    const res = await banProjectMember({ projectId, userId: TARGET, scope: "org" })
    expect(res.result).toBe(false)
    // Nothing applied because the guard runs before applyBan.
    expect(await bannedAtOf(projectId, TARGET)).toBeNull()
    expect(await bannedAtOf(p2.id, TARGET)).toBeNull()
  })

  it("bans an org member who has NO project_access row (upsert, not a silent no-op)", async () => {
    // TARGET2 is an org member but was never granted project_access (no row). A bare
    // UPDATE would touch 0 rows and the ban would be silently ineffective on the bus;
    // applyBan upserts a banned row so resolveConnection's bannedAt gate fires.
    expect(await bannedAtOf(projectId, TARGET2)).toBeNull() // no row exists at all
    const res = await banProjectMember({ projectId, userId: TARGET2, scope: "project" })
    expect(res.result).toBe(true)
    expect(await bannedAtOf(projectId, TARGET2)).not.toBeNull()
  })
})

describe("banned owner cannot self-unban or retaliate (governance takeover guard)", () => {
  beforeEach(async () => {
    // Promote TARGET to a second owner so neither is the "last owner", then OWNER
    // bans co-owner TARGET. (Outer beforeEach already reset state + actingUserId=OWNER.)
    await db
      .update(projectAccess)
      .set({ level: "owner" })
      .where(and(eq(projectAccess.projectId, projectId), eq(projectAccess.userId, TARGET)))
    const banned = await banProjectMember({ projectId, userId: TARGET, scope: "project" })
    expect(banned.result).toBe(true)
    expect(await bannedAtOf(projectId, TARGET)).not.toBeNull()
  })

  it("a banned owner cannot unban themselves", async () => {
    actingUserId = TARGET // the banned co-owner acts
    const res = await unbanProjectMember({ projectId, userId: TARGET, scope: "project" })
    expect(res.result).toBe(false)
    expect(await bannedAtOf(projectId, TARGET)).not.toBeNull() // still banned
  })

  it("a banned owner cannot retaliate by banning the manager who banned them", async () => {
    actingUserId = TARGET // banned co-owner tries to ban OWNER
    const res = await banProjectMember({ projectId, userId: OWNER, scope: "project" })
    expect(res.result).toBe(false)
    expect(await bannedAtOf(projectId, OWNER)).toBeNull()
  })
})

/**
 * Thread-knowledge purge from the dashboard (FEAT-0004 L3).
 *
 * The purge logic itself is @relayroom/db's and tested there; these cover the web
 * action's contract: owner-only (checked from the action, not by which button
 * renders), dry-run counts without deleting, and the real purge honoring the
 * (다) semantic - sole-source entries deleted, multi-source entries refused. A
 * separate suite covers which statuses set the knowledge marker when a thread is
 * closed from the dashboard.
 */
import { afterAll, beforeEach, describe, expect, it, vi } from "vitest"
import { eq } from "drizzle-orm"

let actingUserId = "pg-owner"

vi.mock("@/lib/auth-session", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@/lib/auth-session")>()
  return { ...actual, getServerSession: vi.fn(async () => ({ user: { id: actingUserId } })) }
})

import { and, eq as eqCol } from "drizzle-orm"
import { db } from "@/lib/db"
import { projects, projectAccess, knowledge, threads, threadExtractions } from "@relayroom/db/schema"
import { better_auth_user, better_auth_organization, better_auth_member } from "@relayroom/db/auth-schema"
import { purgeThreadKnowledge, searchPurgeableThreads } from "./purge-actions"

const ORG = "org-pg"
const OWNER = "pg-owner"
const WRITER = "pg-writer"
const THREAD_A = "00000000-0000-0000-0000-00000000000a"
const THREAD_B = "00000000-0000-0000-0000-00000000000b"
/** Seeded in a SECOND project, to aim the action across the boundary on purpose. */
const THREAD_FOREIGN = "00000000-0000-0000-0000-00000000000f"

let projectId: string
let otherProjectId: string

async function seedMember(id: string, role: string) {
  await db.insert(better_auth_user).values({ id, name: id, email: `${id}@t.local`, emailVerified: true }).onConflictDoNothing()
  await db.insert(better_auth_member).values({ id: `m-${id}`, organizationId: ORG, userId: id, role, createdAt: new Date() }).onConflictDoNothing()
}

async function addEntry(refs: { threadId?: string }[], title = "k"): Promise<string> {
  const [r] = await db
    .insert(knowledge)
    .values({ projectId, kind: "fact", title, body: "b", sourceKind: "learn", sourceRefs: refs })
    .returning({ id: knowledge.id })
  return r!.id
}

async function exists(id: string): Promise<boolean> {
  const [r] = await db.select({ id: knowledge.id }).from(knowledge).where(eq(knowledge.id, id))
  return !!r
}

async function refsOf(id: string) {
  const [r] = await db.select({ refs: knowledge.sourceRefs }).from(knowledge).where(eq(knowledge.id, id))
  return r?.refs ?? []
}

/** Did purge leave the "do not extract this again" record for a thread? */
async function watermarkReason(pid: string, threadId: string): Promise<string | null> {
  const [r] = await db
    .select({ reason: threadExtractions.reason })
    .from(threadExtractions)
    .where(and(eqCol(threadExtractions.projectId, pid), eqCol(threadExtractions.threadId, threadId)))
  return r?.reason ?? null
}

beforeEach(async () => {
  actingUserId = OWNER
  await db.delete(knowledge)
  await db.delete(threadExtractions)
  await db.delete(threads)
  await db.delete(projectAccess)
  await db.delete(projects).where(eq(projects.organizationId, ORG))
  await db.delete(better_auth_member).where(eq(better_auth_member.organizationId, ORG))
  await db.insert(better_auth_organization).values({ id: ORG, name: ORG, createdAt: new Date() }).onConflictDoNothing()
  await seedMember(OWNER, "member")
  await seedMember(WRITER, "member")

  const [p] = await db.insert(projects).values({ organizationId: ORG, slug: "pg", name: "PG", connectCode: "pg-cc", createdByUserId: OWNER }).returning({ id: projects.id })
  projectId = p!.id
  const [other] = await db.insert(projects).values({ organizationId: ORG, slug: "pg2", name: "PG2", connectCode: "pg2-cc", createdByUserId: OWNER }).returning({ id: projects.id })
  otherProjectId = other!.id
  await db.insert(projectAccess).values([
    { projectId, userId: OWNER, level: "owner", createdByUserId: OWNER },
    { projectId, userId: WRITER, level: "write", createdByUserId: OWNER },
  ])

  // The threads must exist as rows. purgeKnowledgeFromThread now checks that the
  // thread belongs to the project before writing anything, so a bare uuid that
  // names no thread is rejected rather than quietly treated as "nothing to purge".
  await db.insert(threads).values([
    { id: THREAD_A, projectId, subject: "leaked secret discussion" },
    { id: THREAD_B, projectId, subject: "unrelated planning" },
    { id: THREAD_FOREIGN, projectId: otherProjectId, subject: "another project's thread" },
  ])
})

afterAll(async () => {
  await db.$client.end()
})

describe("purgeThreadKnowledge", () => {
  it("dry-run reports what would happen and changes nothing", async () => {
    const sole = await addEntry([{ threadId: THREAD_A }], "sole")
    const multi = await addEntry([{ threadId: THREAD_A }, { threadId: THREAD_B }], "multi")

    const res = await purgeThreadKnowledge(projectId, THREAD_A, true)
    expect(res.result).toBe(true)
    if (!res.result) return
    // A multi-source entry is refused, not detached: purge cannot remove this
    // thread's contribution without deleting text another thread also produced,
    // and silently keeping it was the shape of BUG-0010.
    expect(res.item.complete).toBe(false)
    expect(res.item.deleted).toBe(1)
    if (res.item.complete) return
    expect(res.item.refused).toEqual([multi])

    // Nothing changed.
    expect(await exists(sole)).toBe(true)
    expect((await refsOf(multi))).toHaveLength(2)
  })

  it("real purge deletes what it can and leaves the multi-source entry untouched", async () => {
    const sole = await addEntry([{ threadId: THREAD_A }], "sole")
    const multi = await addEntry([{ threadId: THREAD_A }, { threadId: THREAD_B }], "multi")
    const untouched = await addEntry([{ threadId: THREAD_B }], "other-thread")

    const res = await purgeThreadKnowledge(projectId, THREAD_A, false)
    expect(res.result).toBe(true)
    if (!res.result) return
    expect(res.item.complete).toBe(false)
    expect(res.item.deleted).toBe(1)

    expect(await exists(sole)).toBe(false)            // sole source -> deleted
    expect(await exists(multi)).toBe(true)            // multi -> kept, and kept WHOLE
    // Its refs are intact. Stripping this thread out is what the old detach did,
    // and it left text derived from the purged thread behind while reporting
    // success.
    expect(await refsOf(multi)).toHaveLength(2)
    expect(await exists(untouched)).toBe(true)        // another thread -> untouched
    expect(await refsOf(untouched)).toEqual([{ threadId: THREAD_B }])
  })

  it("refuses a write grant (owner is the bar), and deletes nothing", async () => {
    const sole = await addEntry([{ threadId: THREAD_A }])
    actingUserId = WRITER
    const res = await purgeThreadKnowledge(projectId, THREAD_A, false)
    expect(res.result).toBe(false)
    expect(await exists(sole)).toBe(true)
  })

  it("a thread with no derived knowledge is a clean zero", async () => {
    const res = await purgeThreadKnowledge(projectId, THREAD_A, true)
    expect(res.result).toBe(true)
    if (res.result) expect(res.item).toEqual({ complete: true, deleted: 0 })
  })
})

/**
 * The remedy in the 0.5.2 release note: an operator whose purged knowledge came
 * back re-runs the purge after upgrading. Everything below is that sentence.
 *
 * The thread they must reach has ZERO citing entries - the earlier purge removed
 * them - so every assertion here uses a thread with no knowledge. That is the case
 * the old flow could neither offer in the picker nor execute once chosen, and a
 * "purge deletes rows" test passes happily while it is broken.
 */
describe("purging a thread that no knowledge cites (the BUG-0010 remedy)", () => {
  it("records the purged watermark through the owner surface, with nothing to delete", async () => {
    expect(await watermarkReason(projectId, THREAD_A)).toBeNull()

    const res = await purgeThreadKnowledge(projectId, THREAD_A, false)

    expect(res.result).toBe(true)
    if (!res.result) return
    expect(res.item).toEqual({ complete: true, deleted: 0 })
    // The count is zero and the operation still did the thing it was for.
    expect(await watermarkReason(projectId, THREAD_A)).toBe("purged")
  })

  it("overwrites an earlier 'extracted' claim, so a distilled thread can still be suppressed", async () => {
    await db.insert(threadExtractions).values({ projectId, threadId: THREAD_A, reason: "extracted" })

    const res = await purgeThreadKnowledge(projectId, THREAD_A, false)
    expect(res.result).toBe(true)
    expect(await watermarkReason(projectId, THREAD_A)).toBe("purged")
  })

  it("NEGATIVE CONTROL: the dry run the confirm dialog depends on writes no watermark", async () => {
    // The UI always dry-runs to fill in the confirmation. If that left a
    // watermark, an owner who then clicked Cancel would have silently suppressed
    // the thread anyway - a destructive preview.
    const res = await purgeThreadKnowledge(projectId, THREAD_A, true)
    expect(res.result).toBe(true)
    expect(await watermarkReason(projectId, THREAD_A)).toBeNull()
  })

  it("refuses a write grant here too, and leaves no watermark", async () => {
    actingUserId = WRITER
    const res = await purgeThreadKnowledge(projectId, THREAD_A, false)
    expect(res.result).toBe(false)
    expect(await watermarkReason(projectId, THREAD_A)).toBeNull()
  })
})

describe("project boundary", () => {
  it("cannot watermark another project's thread by naming its id", async () => {
    // OWNER owns `projectId`. Aiming the action at a thread that lives in
    // otherProjectId must fail, and must not leave a record against either
    // project - the danger of the watermark is that it silently stops another
    // project from learning.
    const res = await purgeThreadKnowledge(projectId, THREAD_FOREIGN, false)

    expect(res.result).toBe(false)
    expect(await watermarkReason(projectId, THREAD_FOREIGN)).toBeNull()
    expect(await watermarkReason(otherProjectId, THREAD_FOREIGN)).toBeNull()
  })

  it("refuses it on the dry run too, so the error cannot be used to probe for a thread id", async () => {
    const res = await purgeThreadKnowledge(projectId, THREAD_FOREIGN, true)
    expect(res.result).toBe(false)
  })
})

describe("searchPurgeableThreads", () => {
  it("finds a thread with no knowledge at all - the one the default list cannot offer", async () => {
    const res = await searchPurgeableThreads(projectId, "leaked")
    expect(res.result).toBe(true)
    if (!res.result) return
    expect(res.items).toHaveLength(1)
    expect(res.items[0]!.threadId).toBe(THREAD_A)
    expect(res.items[0]!.entryCount).toBe(0)
  })

  it("counts citing entries when there are some", async () => {
    await addEntry([{ threadId: THREAD_A }], "sole")
    await addEntry([{ threadId: THREAD_A }, { threadId: THREAD_B }], "multi")

    const res = await searchPurgeableThreads(projectId, "leaked")
    expect(res.result).toBe(true)
    if (!res.result) return
    expect(res.items[0]!.entryCount).toBe(2)
  })

  it("never returns another project's thread", async () => {
    const res = await searchPurgeableThreads(projectId, "another project")
    expect(res.result).toBe(true)
    if (!res.result) return
    expect(res.items).toHaveLength(0)
  })

  it("refuses a write grant - it must not become a way to enumerate thread subjects", async () => {
    actingUserId = WRITER
    const res = await searchPurgeableThreads(projectId, "leaked")
    expect(res.result).toBe(false)
  })
})

/**
 * Human promotion from the dashboard (FEAT-0001 L0).
 *
 * L0's entire safety argument is that a person is the only thing that can
 * promote: agents write candidates and cannot vouch for their own guesses. So
 * these test the gate from the ACTION side, not by observing which buttons get
 * drawn - a Server Action is a live endpoint that a caller reaches without ever
 * loading the page, and "the button is hidden" is not an authorization check.
 *
 * The invariant that matters most is the second promote. The audit table is
 * supposed to answer "when did this become trusted, and who decided"; if a
 * repeat click appends another row, the ledger starts reporting decisions that
 * never happened.
 */
import { afterAll, beforeEach, describe, expect, it, vi } from "vitest"
import { eq } from "drizzle-orm"

let actingUserId = "kp-owner"

vi.mock("@/lib/auth-session", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@/lib/auth-session")>()
  return {
    ...actual, // keep the REAL requireProjectAccess
    getServerSession: vi.fn(async () => ({ user: { id: actingUserId } })),
  }
})

import { db } from "@/lib/db"
import {
  projects,
  projectAccess,
  knowledge,
  knowledgeValidations,
  knowledgeAudits,
} from "@relayroom/db/schema"
import {
  better_auth_user,
  better_auth_organization,
  better_auth_member,
} from "@relayroom/db/auth-schema"
import { promoteKnowledge } from "./actions"

const ORG = "org-kp"
const OWNER = "kp-owner"       // project_access owner
const WRITER = "kp-writer"     // project_access write
const ORG_ADMIN = "kp-orgadmin" // org admin, NO project_access row
const BANNED = "kp-banned"     // owner grant, but banned
const OUTSIDER = "kp-outsider" // member of another org

let projectId: string
let otherProjectId: string
let entryId: string

async function seedMember(org: string, id: string, role: string) {
  await db
    .insert(better_auth_user)
    .values({ id, name: id, email: `${id}@test.local`, emailVerified: true })
    .onConflictDoNothing()
  await db
    .insert(better_auth_member)
    .values({ id: `m-${org}-${id}`, organizationId: org, userId: id, role, createdAt: new Date() })
    .onConflictDoNothing()
}

async function addEntry(pid: string, state = "candidate"): Promise<string> {
  const [row] = await db
    .insert(knowledge)
    .values({
      projectId: pid,
      kind: "fact",
      title: "a claim",
      body: "the body",
      sourceKind: "learn",
      validationState: state,
    })
    .returning({ id: knowledge.id })
  return row!.id
}

async function stateOf(id: string) {
  const [row] = await db
    .select({ state: knowledge.validationState, promotedAt: knowledge.promotedAt })
    .from(knowledge)
    .where(eq(knowledge.id, id))
  return row
}

async function auditRows(id: string) {
  return db
    .select({ action: knowledgeAudits.action, from: knowledgeAudits.fromState, to: knowledgeAudits.toState, actor: knowledgeAudits.actorUserId, detail: knowledgeAudits.detail })
    .from(knowledgeAudits)
    .where(eq(knowledgeAudits.knowledgeId, id))
}

async function validationRows(id: string) {
  return db
    .select({ issuer: knowledgeValidations.issuer, issuerId: knowledgeValidations.issuerId, signal: knowledgeValidations.signal, counted: knowledgeValidations.counted })
    .from(knowledgeValidations)
    .where(eq(knowledgeValidations.knowledgeId, id))
}

beforeEach(async () => {
  actingUserId = OWNER
  await db.delete(knowledge)
  await db.delete(projectAccess)
  for (const org of [ORG, "org-kp-other"]) {
    await db.delete(projects).where(eq(projects.organizationId, org))
    await db.delete(better_auth_member).where(eq(better_auth_member.organizationId, org))
    await db
      .insert(better_auth_organization)
      .values({ id: org, name: org, createdAt: new Date() })
      .onConflictDoNothing()
  }

  await seedMember(ORG, OWNER, "member")
  await seedMember(ORG, WRITER, "member")
  await seedMember(ORG, BANNED, "member")
  await seedMember(ORG, ORG_ADMIN, "admin")
  await seedMember("org-kp-other", OUTSIDER, "owner")

  const [p] = await db
    .insert(projects)
    .values({ organizationId: ORG, slug: "kp", name: "KP", connectCode: "kp-cc", createdByUserId: OWNER })
    .returning({ id: projects.id })
  projectId = p!.id

  const [other] = await db
    .insert(projects)
    .values({ organizationId: "org-kp-other", slug: "kp-other", name: "KPO", connectCode: "kp-cc-o", createdByUserId: OUTSIDER })
    .returning({ id: projects.id })
  otherProjectId = other!.id

  await db.insert(projectAccess).values([
    { projectId, userId: OWNER, level: "owner", createdByUserId: OWNER },
    { projectId, userId: WRITER, level: "write", createdByUserId: OWNER },
    { projectId, userId: BANNED, level: "owner", bannedAt: new Date(), bannedByUserId: OWNER, createdByUserId: OWNER },
  ])

  entryId = await addEntry(projectId)
})

afterAll(async () => {
  await db.$client.end()
})

describe("an owner promoting", () => {
  it("writes validation, state, promotedAt and audit in one go", async () => {
    const res = await promoteKnowledge({ projectId, knowledgeId: entryId })
    expect(res.result).toBe(true)

    const after = await stateOf(entryId)
    expect(after?.state).toBe("trusted")
    expect(after?.promotedAt).not.toBeNull()

    const validations = await validationRows(entryId)
    expect(validations).toHaveLength(1)
    expect(validations[0]).toMatchObject({
      issuer: "human",
      issuerId: OWNER,
      signal: "support",
      counted: true,
    })

    const audits = await auditRows(entryId)
    expect(audits).toHaveLength(1)
    expect(audits[0]).toMatchObject({
      action: "promote",
      from: "candidate",
      to: "trusted",
      actor: OWNER,
    })
    // The override is what makes K=1 legible after the fact.
    expect(audits[0]!.detail).toMatchObject({ override: true })
  })

  it("is idempotent: promoting twice leaves ONE audit row", async () => {
    await promoteKnowledge({ projectId, knowledgeId: entryId })
    const first = await stateOf(entryId)

    const second = await promoteKnowledge({ projectId, knowledgeId: entryId })
    expect(second.result).toBe(true) // already trusted is not an error

    expect(await auditRows(entryId)).toHaveLength(1)
    expect(await validationRows(entryId)).toHaveLength(1)
    // promotedAt must not move either - it records when it BECAME trusted.
    expect((await stateOf(entryId))?.promotedAt?.getTime()).toBe(first?.promotedAt?.getTime())
  })
})

describe("who may not promote", () => {
  it("refuses a write grant - owner is the bar", async () => {
    actingUserId = WRITER
    const res = await promoteKnowledge({ projectId, knowledgeId: entryId })
    expect(res.result).toBe(false)

    expect((await stateOf(entryId))?.state).toBe("candidate")
    expect(await auditRows(entryId)).toHaveLength(0)
    expect(await validationRows(entryId)).toHaveLength(0)
  })

  it("refuses a banned member who still holds an owner grant", async () => {
    actingUserId = BANNED
    const res = await promoteKnowledge({ projectId, knowledgeId: entryId })
    expect(res.result).toBe(false)
    expect((await stateOf(entryId))?.state).toBe("candidate")
  })

  it("refuses a member of another org", async () => {
    actingUserId = OUTSIDER
    const res = await promoteKnowledge({ projectId, knowledgeId: entryId })
    expect(res.result).toBe(false)
    expect((await stateOf(entryId))?.state).toBe("candidate")
  })
})

describe("org owner/admin with no explicit grant", () => {
  it("may promote - the effective-owner rule reaches this path too", async () => {
    actingUserId = ORG_ADMIN
    const res = await promoteKnowledge({ projectId, knowledgeId: entryId })
    expect(res.result).toBe(true)
    expect((await stateOf(entryId))?.state).toBe("trusted")
    expect(await auditRows(entryId)).toHaveLength(1)
  })
})

describe("tenant boundary", () => {
  it("will not promote another project's entry, even for its own owner", async () => {
    const foreign = await addEntry(otherProjectId)
    actingUserId = OWNER

    // The caller's own project passes the access gate; the entry belongs elsewhere.
    const res = await promoteKnowledge({ projectId, knowledgeId: foreign })
    expect(res.result).toBe(false)

    expect((await stateOf(foreign))?.state).toBe("candidate")
    expect(await auditRows(foreign)).toHaveLength(0)
  })
})
